def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y-1,x), (y+1,x), (y,x-1), (y,x+1)):
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            rs = [p[0] for p in cells]
            cs = [p[1] for p in cells]
            comps.append({
                "color": color, "cells": cells,
                "r": sum(rs) / len(rs), "c": sum(cs) / len(cs),
                "rmin": min(rs), "rmax": max(rs),
                "cmin": min(cs), "cmax": max(cs)
            })

    best = None
    for comp in comps:
        r0, r1 = comp["rmin"], comp["rmax"]
        c0, c1 = comp["cmin"], comp["cmax"]
        if r0 == r1 or c0 == c1:
            continue
        cells = set(comp["cells"])
        for er in (r0, r1):
            for ec in (c0, c1):
                arm = {(r, c) for r, c in cells if r == er or c == ec}
                arm_len = (c1-c0+1) + (r1-r0+1) - 1
                # Favor components that mostly lie on two perpendicular arms.
                score = len(arm) / max(1, len(cells)) + len(arm) / arm_len
                dr = 1 if er == r0 else -1
                dc = 1 if ec == c0 else -1

                targets = []
                for other in comps:
                    if other is comp:
                        continue
                    dy, dx = other["r"] - er, other["c"] - ec
                    if dy * dr > 0 and dx * dc > 0:
                        dist = (dy / h) ** 2 + (dx / w) ** 2
                        targets.append((dist, other))
                if not targets:
                    continue
                dist, target = min(targets, key=lambda x: x[0])
                candidate = (score, -dist, comp, target)
                if best is None or candidate[:2] > best[:2]:
                    best = candidate

    if best is not None:
        marker, target = best[2], best[3]
        for r, c in target["cells"]:
            out[r][c] = marker["color"]
    return out
